using UnityEngine;
using HNP.World;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var game = Object.FindFirstObjectByType<HnpWorldGame>();
            result.Log("player=" + game.player.transform.position + " visual=" + game.visual.lossyScale + " camera=" + game.viewCamera.transform.position);
            foreach (var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))
                if (r.bounds.size.magnitude > 30)
                    result.Log(r.name + " enabled=" + r.enabled + " mesh=" + r.GetComponent<MeshFilter>().sharedMesh.name + " bounds=" + r.bounds);
        }
    }
}
